// 注意：快递 100 的查询接口不返回 Access-Control-Allow-Origin，
// 因此在浏览器里直接打开 BotCraft.html 时会被跨域策略拦掉；
// 桌面版 exe 走 Python 侧代理（不受同源限制）可以正常调用。
var COM = { '圆通': 'yuantong', '中通': 'zhongtong', '申通': 'shentong',
            '韵达': 'yunda', '顺丰': 'shunfeng', '京东': 'jd', 'EMS': 'ems' };
plugin.register('track_express', async function (args, ctx) {
  var no = String((args && args.number) || '').trim();
  var com = String((args && args.company) || '').trim();
  if (!no) return { error: '缺少参数 number（快递单号）' };
  var code = COM[com] || com;
  var r = await plugin.host.fetch('https://www.kuaidi100.com/query?type=' + encodeURIComponent(code)
    + '&postid=' + encodeURIComponent(no) + '&temp=' + Math.random());
  var j = JSON.parse(r.text);
  if (!j || j.message !== 'ok') return { error: (j && j.message) || '查询失败，请检查单号与快递公司' };
  return {
    company: j.com || com, number: j.nu || no, state: j.state || '',
    status: j.status || '',
    traces: (j.data || []).map(function (t) { return (t.time || '') + '  ' + (t.context || ''); })
  };
});
